  // ── Status helpers ──────────────────────────────────────────────────────────

  Color _getStatusColor(String status) {
    switch (status.toUpperCase()) {
      case 'CONFIRMED':
        return const Color(0xFF0891B2);  // cyan
      case 'IN_PROGRESS':
        return const Color(0xFF7C3AED);  // ungu
      case 'DONE':
        return const Color(0xFF059669);  // hijau
      case 'CLOSE':
        return const Color(0xFF92400E);  // coklat
      case 'FAIL':
        return const Color(0xFFDC2626);  // merah
      case 'PENDING':
      default:
        return const Color(0xFFD97706);  // oranye
    }
  }

  String _getStatusLabel(String status) {
    switch (status.toUpperCase()) {
      case 'PENDING':
        return LanguageService.tr('status_pending');
      case 'CONFIRMED':
        return LanguageService.tr('status_confirmed');
      case 'IN_PROGRESS':
        return LanguageService.tr('status_in_progress');
      case 'DONE':
        return LanguageService.tr('status_done');
      case 'CLOSE':
        return LanguageService.tr('status_closed');
      case 'FAIL':
        return LanguageService.tr('status_failed');
      default:
        return LanguageService.tr('status_pending');
    }
  }

  IconData _getStatusIcon(String status) {
    switch (status.toUpperCase()) {
      case 'CONFIRMED':
        return Icons.how_to_reg_rounded;
      case 'IN_PROGRESS':
        return Icons.timelapse_rounded;
      case 'DONE':
        return Icons.check_circle_rounded;
      case 'CLOSE':
        return Icons.block_rounded;
      case 'FAIL':
        return Icons.cancel_rounded;
      case 'PENDING':
      default:
        return Icons.schedule_rounded;
    }
  }

  Color _getUrgencyColor(String urgency) {
    if (urgency.toLowerCase().contains('sangat')) return const Color(0xFFDC2626);
    if (urgency.toLowerCase().contains('penting')) return const Color(0xFFD97706);
    return const Color(0xFF1D4ED8);
  }

