  // ── Avatar ──────────────────────────────────────────────────────────────────

  Widget _buildDeceasedAvatarImage(String? attachmentUrl) {
    if (attachmentUrl != null && attachmentUrl.isNotEmpty) {
      if (attachmentUrl.startsWith('data:image')) {
        try {
          final base64Content = attachmentUrl.split(',').last;
          final bytes = base64Decode(base64Content);
          return Image.memory(bytes, width: 92, height: 92, fit: BoxFit.cover,
              errorBuilder: (_, __, ___) => _defaultAvatar());
        } catch (_) {
          return _defaultAvatar();
        }
      } else if (attachmentUrl.startsWith('http://') ||
          attachmentUrl.startsWith('https://')) {
        return Image.network(attachmentUrl, width: 92, height: 92,
            fit: BoxFit.cover,
            errorBuilder: (_, __, ___) => _defaultAvatar());
      } else if (attachmentUrl.startsWith('assets/')) {
        return Image.asset(attachmentUrl, width: 92, height: 92,
            fit: BoxFit.cover,
            errorBuilder: (_, __, ___) => _defaultAvatar());
      } else {
        final file = File(attachmentUrl);
        if (file.existsSync()) {
          return Image.file(file, width: 92, height: 92, fit: BoxFit.cover,
              errorBuilder: (_, __, ___) => _defaultAvatar());
        }
      }
    }
    return _defaultAvatar();
  }

  Widget _defaultAvatar() {
